export type FbGroup = { id: string; name: string; niche: string; members: number | null; url: string; custom?: boolean; source?: string };

export function normalizeFacebookGroup(value: string): string | null {
  try {
    const url = new URL(value.trim());
    if (url.protocol !== "https:" && url.protocol !== "http:") return null;
    if (url.username || url.password || url.port || !["facebook.com", "www.facebook.com", "m.facebook.com", "web.facebook.com", "fb.com", "www.fb.com"].includes(url.hostname.toLowerCase())) return null;
    const match = url.pathname.match(/^\/groups\/([A-Za-z0-9._-]+)\/?$/);
    return match ? `https://www.facebook.com/groups/${match[1]}` : null;
  } catch { return null; }
}

